import 'package:flutter/material.dart';
import '../models/download_job.dart';
import '../services/download_manager_service.dart';
import '../theme/neumorphic_widgets.dart';

class DownloadManagerScreen extends StatelessWidget{final DownloadManagerService manager;const DownloadManagerScreen({super.key,required this.manager});String _status(DownloadProgress j){switch(j.status){case'queued':return'Queued';case'extracting':return'Preparing';case'downloading':return'Downloading';case'processing':case'converting':return'Converting to MP3';case'saving':return'Saving';case'completed':return'Completed';case'cancelled':return'Cancelled';case'failed':return'Failed';default:return j.status;}}Color _color(DownloadProgress j)=>j.isCompleted?NeuTheme.success:j.isFailed||j.isCancelled?NeuTheme.danger:NeuTheme.accent;
@override Widget build(BuildContext context)=>AnimatedBuilder(animation:manager,builder:(context,_){final jobs=manager.jobs;return Scaffold(appBar:AppBar(title:const Text('Downloads'),actions:[if(jobs.isNotEmpty)NeuIconButton(icon:Icons.refresh_rounded,onPressed:()=>Future.wait(jobs.map((j)=>manager.refreshJob(j.jobId))),active:false),const SizedBox(width:12)]),body:jobs.isEmpty?Center(child:NeuSurface(child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:64,height:64,decoration:BoxDecoration(color:NeuTheme.accent.withValues(alpha:.12),shape:BoxShape.circle),child:const Icon(Icons.download_rounded,size:30,color:NeuTheme.accent)),const SizedBox(height:14),const Text('No downloads yet',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('Your active and recent downloads will appear here.',textAlign:TextAlign.center,style:TextStyle(color:NeuTheme.muted,fontSize:12))]))):ListView.separated(padding:const EdgeInsets.fromLTRB(16,8,16,28),itemCount:jobs.length,separatorBuilder:(_,__)=>const SizedBox(height:12),itemBuilder:(_,i)=>_JobCard(job:jobs[i],manager:manager,status:_status(jobs[i]),color:_color(jobs[i]))));});}
class _JobCard extends StatelessWidget{final DownloadProgress job;final DownloadManagerService manager;final String status;final Color color;const _JobCard({required this.job,required this.manager,required this.status,required this.color});@override Widget build(BuildContext context){final p=(job.progress/100).clamp(0.0,1.0);return NeuSurface(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Container(width:42,height:42,decoration:BoxDecoration(color:color.withValues(alpha:.12),borderRadius:BorderRadius.circular(12)),child:Icon(job.isCompleted?Icons.check_rounded:job.isFailed||job.isCancelled?Icons.error_outline_rounded:Icons.music_note_rounded,color:color)),const SizedBox(width:12),Expanded(child:Text(job.filename.isNotEmpty?job.filename:(job.url??'Audio download'),maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w700))),PopupMenuButton<String>(onSelected:(v)async{if(v=='cancel')await manager.cancel(job.jobId);if(v=='retry')await manager.retry(job.jobId);if(v=='delete')await manager.remove(job.jobId);},itemBuilder:(_)=>[if(job.isActive)const PopupMenuItem(value:'cancel',child:Text('Cancel download')),if(job.isFailed||job.isCancelled)const PopupMenuItem(value:'retry',child:Text('Retry download')),if(job.isFinished)const PopupMenuItem(value:'delete',child:Text('Remove from list'))])]),const SizedBox(height:14),Row(children:[Text(status,style:TextStyle(color:color,fontWeight:FontWeight.w800)),const Spacer(),if(job.isActive)Text('${job.progress.toStringAsFixed(0)}%',style:const TextStyle(color:NeuTheme.muted,fontWeight:FontWeight.w700))]),if(job.isActive)...[const SizedBox(height:9),ClipRRect(borderRadius:BorderRadius.circular(8),child:LinearProgressIndicator(value:p,minHeight:8,backgroundColor:NeuTheme.input,color:NeuTheme.accent)),const SizedBox(height:8),Row(children:[if(job.speed.isNotEmpty)Text(job.speed,style:const TextStyle(color:NeuTheme.muted,fontSize:12)),const Spacer(),if(job.eta!=null&&job.eta!>0)Text('ETA ${job.eta}s',style:const TextStyle(color:NeuTheme.muted,fontSize:12))])],if(job.error!=null&&job.error!.isNotEmpty)...[const SizedBox(height:9),Text(job.error!,style:const TextStyle(color:NeuTheme.danger,fontSize:12))],if(job.isFailed||job.isCancelled)...[const SizedBox(height:12),NeuButton(onPressed:()=>manager.retry(job.jobId),child:const Row(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.refresh_rounded),SizedBox(width:7),Text('Retry')]))]]));}}
